function progMax(){return[{id:"J",nom:"Jambes",ex:[EX("presse",3,10,100),EX("hack",3,10,40),EX("mollets",3,12,60),EX("legcurl",3,10,37.5)]},{id:"H",nom:"Haut du corps",ex:[EX("tirage",3,10,57.5),EX("chest",3,10,50),EX("rowing",3,10,52.5),EX("epaules",3,10,32.5)]}]}
function progExemple(){return[{id:"J",nom:"Jambes (exemple)",ex:[EX("presse",3,10,40),EX("hack",3,10,null),EX("legext",3,12,20),EX("mollets",3,12,30)]},{id:"H",nom:"Haut du corps (exemple)",ex:[EX("tirage",3,10,25),EX("chest",3,10,20),EX("rowing",3,10,20),EX("epaules",3,10,10)]},{id:"C",nom:"Corps entier (exemple)",ex:[EX("presse",3,10,40),EX("tirage",3,10,25),EX("chest",3,10,20),EX("legcurl",3,10,15)]}]}
function init(who){
 const s={repos:90,screen:"onb1",tab:"auj",user:{nom:"",niveau:null},seuil:5,prog:[],hist:[],fiche:{},first:{},next:"J",sess:null,ex:null,step:1,secu:null,cran:3,sheet:null,mal:5,snack:null,review:false,eq:"Tout",mus:"Tous",msel:[],q:"",edit:null,ereg:null,rest:null,mach:null,hs:null,fromProg:false};
 if(who==="max"){s.demo=true;s.user={nom:"Max",niveau:"connais"};s.prog=progMax();s.hist=histMax();s.screen="auj";s.next="J";
  Object.keys(CAT).forEach(k=>{s.fiche[k]={vals:CAT[k].reg.map(r=>[r[0],r[1]==="cran"?"cran "+r[2]:r[1]]),senti:CAT[k].sentir}})}
 if(who==="alex"){s.real=true;s.user={nom:"Alex",niveau:"connais"};s.repos=90;s.seuil=4;s.prog=JSON.parse(JSON.stringify(ALEX_PROG));s.hist=JSON.parse(JSON.stringify(ALEX_HIST)).map(h=>({...h,d:fdate(h.ts)}));s.screen="auj";s.next="H2";
  Object.keys(ALEX_CAT).forEach(k=>{s.fiche[k]={vals:CAT[k].reg.map(r=>[r[0],r[1]]),senti:CAT[k].sentir}})}
 if(who==="nina"){s.user={nom:"Nina",niveau:"debute"};s.prog=progExemple();s.screen="auj";s.next="J";s.first={hack:true};
  ["presse","legext","mollets"].forEach(k=>{s.fiche[k]={vals:CAT[k].reg.map(r=>[r[0],r[1]==="cran"?"cran "+r[2]:r[1]]),senti:CAT[k].sentir}})}
 return s}
const seanceById=(s,id)=>s.prog.find(p=>p.id===id);
const altLibre=(s,k)=>{const a=CAT[k].alt,S=s.sess;return !(S&&(S.done[a]||S.stop[a]||a===k))};
const cfg=(s,k)=>{if(s.sess){if(s.sess.extra&&s.sess.extra[k])return s.sess.extra[k];const sp=seanceById(s,s.sess.sid),sx=sp&&sp.ex.find(x=>x.m===k);if(sx)return sx}for(const p of s.prog)for(const x of p.ex)if(x.m===k)return x;return EX(k,3,10,20)};
function rows(s,k){const R=s.sess.rows;if(!R[k]){const c=cfg(s,k);R[k]=Array.from({length:c.sets},()=>({kg:c.kg==null?(s.real?0:20):c.kg,reps:c.reps,st:"todo",corr:null}))}return R[k]}
